"use strict";(self.webpackChunkwww=self.webpackChunkwww||[]).push([[25966],{46125:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>i,contentTitle:()=>r,default:()=>l,frontMatter:()=>s,metadata:()=>d,toc:()=>o});var a=n(31085),h=n(71184);const s={sidebar_position:9,slug:"/bible/1_Machabees/1_Machabees_9",title:"1 Machabees 9",hide_table_of_contents:!0},r="1 Machabees",d={id:"bible/1 Machabees/1 Machabees 9",title:"1 Machabees 9",description:"Chapter 9",source:"@site/docs/bible/1 Machabees/1 Machabees 9.md",sourceDirName:"bible/1 Machabees",slug:"/bible/1_Machabees/1_Machabees_9",permalink:"/bibleNotes/docs/bible/1_Machabees/1_Machabees_9",draft:!1,unlisted:!1,editUrl:"https://github.com/ozkey/bibleNotes/tree/main/packages/www/docs/bible/1 Machabees/1 Machabees 9.md",tags:[],version:"current",sidebarPosition:9,frontMatter:{sidebar_position:9,slug:"/bible/1_Machabees/1_Machabees_9",title:"1 Machabees 9",hide_table_of_contents:!0},sidebar:"bibleSidebar",previous:{title:"1 Machabees 8",permalink:"/bibleNotes/docs/bible/1_Machabees/1_Machabees_8"},next:{title:"1 Machabees 10",permalink:"/bibleNotes/docs/bible/1_Machabees/1_Machabees_10"}},i={},o=[{value:"Chapter 9",id:"chapter-9",level:2}];function c(e){const t={h1:"h1",h2:"h2",p:"p",...(0,h.R)(),...e.components},{BibleText:n}=t;return n||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("BibleText",!0),(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.h1,{id:"1-machabees",children:"1 Machabees"}),"\n",(0,a.jsx)(t.h2,{id:"chapter-9",children:"Chapter 9"}),"\n",(0,a.jsx)(t.p,{children:"Bacchides is sent again into Judea:  Judas fights against him with eight hundred men and is slain.  Jonathan succeeds him and revenges the murder of his brother John.  He fights against Bacchides.  Alcimus dies miserably.  Bacchides besieges Bethbessen.  He is forced to raise the siege and leave the country."}),"\n",(0,a.jsx)(n,{verse:1,children:"In the mean time, when Demetrius heard that Nicanor and his army were fallen in battle, he sent again Bacchides and Alcimus into Judea; and the right wing of his army with them."}),"\n",(0,a.jsx)(n,{verse:2,children:"And they took the road that leadeth to Galgal, and they camped in Masaloth, which is in Arabella: and they made themselves masters of it, and slew many people."}),"\n",(0,a.jsx)(n,{verse:3,children:"In the first month of the hundred and fifty-second year they brought the army to Jerusalem:"}),"\n",(0,a.jsx)(n,{verse:4,children:"And they arose and went to Berea, with twenty thousand men, and two thousand horsemen."}),"\n",(0,a.jsx)(n,{verse:5,children:"Now Judas had pitched his tents in Laisa, and three thousand chosen men with him:"}),"\n",(0,a.jsx)(n,{verse:6,children:"And they saw the multitude of the army that they were many, and they were seized with great fear: and many withdrew themselves out of the camp, and there remained of them no more than eight hundred men."}),"\n",(0,a.jsx)(n,{verse:7,children:"And Judas saw that his army slipped away, and the battle pressed upon him, and his heart was cast down: because he had not time to gather them together, and he was discouraged."}),"\n",(0,a.jsx)(n,{verse:8,children:"Then he said to them that remained: Let us arise, and go against our enemies, if we may be able to fight against them."}),"\n",(0,a.jsx)(n,{verse:9,children:"But they dissuaded him, saying: We shall not be able, but let us save our lives now, and return to our brethren, and then we will fight against them: for we are but few."}),"\n",(0,a.jsx)(n,{verse:10,children:"Then Judas said: God forbid we should do this thing, and flee away from them: but if our time be come, let us die manfully for our brethren, and let us not stain our glory."}),"\n",(0,a.jsx)(n,{verse:11,children:"And the army removed out of the camp, and they stood over against them: and the horsemen were divided into two troops, and the slingers, and the archers, went before the army, and they that were in the front were all men of valour."}),"\n",(0,a.jsx)(n,{verse:12,children:"And Bacchides was in the right wing, and the legion drew near on two sides, and they sounded the trumpets:"}),"\n",(0,a.jsx)(n,{verse:13,children:"And they also that were on Judas's side, even they also cried out, and the earth shook at the noise of the armies: and the battle was fought from morning even unto the evening."}),"\n",(0,a.jsx)(n,{verse:14,children:"And Judas perceived that the stronger part of the army of Bacchides was on the right side, and all the stout of heart came together with him:"}),"\n",(0,a.jsx)(n,{verse:15,children:"And the right wing was discomfited by them, and he pursued them even to the mount Azotus."}),"\n",(0,a.jsx)(n,{verse:16,children:"And they that were in the left wing saw that the right wing was discomfited, and they followed after Judas, and them that were with him, at their back:"}),"\n",(0,a.jsx)(n,{verse:17,children:"And the battle was hard fought, and there fell many wounded of the one side and of the other."}),"\n",(0,a.jsx)(n,{verse:18,children:"And Judas was slain, and the rest fled away."}),"\n",(0,a.jsx)(n,{verse:19,children:"And Jonathan and Simon took Judas, their brother, and buried him in the sepulchre of their fathers, in the city of Modin."}),"\n",(0,a.jsx)(n,{verse:20,children:"And all the people of Israel bewailed him with great lamentation, and they mourned for him many days."}),"\n",(0,a.jsx)(n,{verse:21,children:"And said: How is the mighty man fallen, that saved the people of Israel!"}),"\n",(0,a.jsx)(n,{verse:22,children:"But the rest of the words of the wars of Judas, and of the noble acts that he did, and of his greatness, are not written: for they were very many."}),"\n",(0,a.jsx)(n,{verse:23,children:"And it came to pass, after the death of Judas, that the wicked began to put forth their heads in all the confines of Israel, and all the workers of iniquity rose up."}),"\n",(0,a.jsx)(n,{verse:24,children:"In those days there was a very great famine, and they and all their country yielded to Bacchides."}),"\n",(0,a.jsx)(n,{verse:25,children:"And Bacchides chose the wicked men, and made them lords of the country:"}),"\n",(0,a.jsx)(n,{verse:26,children:"And they sought out, and made diligent search after the friends of Judas, and brought them to Bacchides, and he took vengeance of them, and abused them."}),"\n",(0,a.jsx)(n,{verse:27,children:"And there was a great tribulation in Israel, such as was not since the day, that there was no prophet seen in Israel."}),"\n",(0,a.jsx)(n,{verse:28,children:"And all the friends of Judas came together, and said to Jonathan:"}),"\n",(0,a.jsx)(n,{verse:29,children:"Since thy brother Judas died there is not a man like him to go forth against our enemies, Bacchides, and them that are the enemies of our nation."}),"\n",(0,a.jsx)(n,{verse:30,children:"Now, therefore, we have chosen thee this day to be our prince, and captain, in his stead, to fight our battles."}),"\n",(0,a.jsx)(n,{verse:31,children:"So Jonathan took upon him the government at that time, and rose up in the place of Judas, his brother"}),"\n",(0,a.jsx)(n,{verse:32,children:"And Bacchides had knowledge of it, and sought to kill him."}),"\n",(0,a.jsx)(n,{verse:33,children:"And Jonathan, and Simon, his brother, knew it, and all that were with them: and they fled into the desert of Thecua, and they pitched by the water of the lake Asphar,"}),"\n",(0,a.jsx)(n,{verse:34,children:"And Bacchides understood it, and he came himself, with all his army, over the Jordan, on the sabbath day."}),"\n",(0,a.jsx)(n,{verse:35,children:"And Jonathan sent his brother, a captain of the people, to desire the Nabutheans his friends, that they would lend them their equipage, which was copious."}),"\n",(0,a.jsx)(n,{verse:36,children:"And the children of Jambri came forth out of Madaba, and took John, and all that he had, and went away with them."}),"\n",(0,a.jsx)(n,{verse:37,children:"After this it was told Jonathan, and Simon, his brother, that the children of Jambri made a great marriage, and were bringing the bride out of Madaba, the daughter of one of the great princes of Chanaan, with great pomp."}),"\n",(0,a.jsx)(n,{verse:38,children:"And they remembered the blood of John, their brother: and they went up, and hid themselves under the covert of the mountain."}),"\n",(0,a.jsx)(n,{verse:39,children:"And they lifted up their eyes, and saw: and behold a tumult, and great preparation: and the bridegroom came forth, and his friends, and his brethren to meet them with timbrels, and musical instruments and many weapons."}),"\n",(0,a.jsx)(n,{verse:40,children:"And they rose up against them from the place where they lay in ambush, and slew them, and there fell many wounded, and the rest fled into the mountains, and they took all their spoils:"}),"\n",(0,a.jsx)(n,{verse:41,children:"And the marriage was turned into mourning, and the noise of their musical instruments into lamentation."}),"\n",(0,a.jsx)(n,{verse:42,children:"And they took revenge for the blood of their brother: and they returned to the bank of the Jordan."}),"\n",(0,a.jsx)(n,{verse:43,children:"And Bacchides heard it, and he came on the sabbath day even to the bank of the Jordan, with a great power."}),"\n",(0,a.jsx)(n,{verse:44,children:"And Jonathan said to his company: Let us arise, and fight against our enemies: for it is not now as yesterday, and the day before."}),"\n",(0,a.jsx)(n,{verse:45,children:"For behold the battle is before us, and the water of the Jordan on this side and on that side, and banks, and marshes, and woods: and there is no place for us to turn aside."}),"\n",(0,a.jsx)(n,{verse:46,children:"Now, therefore, cry ye to heaven, that ye may be delivered from the hand of your enemies. And they joined battle."}),"\n",(0,a.jsx)(n,{verse:47,children:"And Jonathan stretched forth his hand to strike Bacchides, but he turned away from him backwards."}),"\n",(0,a.jsx)(n,{verse:48,children:"And Jonathan, and they that were with him, leapt into the Jordan, and swam over the Jordan to them."}),"\n",(0,a.jsx)(n,{verse:49,children:"And there fell of Bacchides' side that day a thousand men: and they returned to Jerusalem,"}),"\n",(0,a.jsx)(n,{verse:50,children:"And they built strong cities in Judea, the fortress that was in Jericho, and in Ammaus, and in Bethoron, and in Bethel, and Thamnata, and Phara, and Thopo, with high walls, and gates, and bars."}),"\n",(0,a.jsx)(n,{verse:51,children:"And he placed garrisons in them, that they might wage war against Israel:"}),"\n",(0,a.jsx)(n,{verse:52,children:"And he fortified the city of Bethsura, and Gazara, and the castle, and set garrisons in them, and provisions of victuals:"}),"\n",(0,a.jsx)(n,{verse:53,children:"And he took the sons of the chief men of the country for hostages, and put them in the castle in Jerusalem in custody."}),"\n",(0,a.jsx)(n,{verse:54,children:"Now in the year one hundred and fifty-three, the second month, Alcimus commanded the walls of the inner court of the sanctuary to be thrown down, and the works of the prophets to be destroyed: and he began to destroy."}),"\n",(0,a.jsx)(n,{verse:55,children:"At that time Alcimus was struck: and his works were hindered, and his mouth was stopped, and he was taken with a palsy, so that he could no more speak a word, nor give order concerning his house."}),"\n",(0,a.jsx)(n,{verse:56,children:"And Alcimus died at that time in great torment."}),"\n",(0,a.jsx)(n,{verse:57,children:"And Bacchides saw that Alcimus was dead: and he returned to the king, and the land was quiet for two years."}),"\n",(0,a.jsx)(n,{verse:58,children:"And all the wicked held a council, saying: Behold Jonathan, and they that are with him, dwell at ease and without fear: now, therefore, let us bring Bacchides hither, and he shall take them all in one night."}),"\n",(0,a.jsx)(n,{verse:59,children:"So they went, and gave him counsel."}),"\n",(0,a.jsx)(n,{verse:60,children:"And he arose to come with a great army: and he sent secretly letters to his adherents that were in Judea to seize upon Jonathan, and them that were with him: but they could not, for their design was known to them."}),"\n",(0,a.jsx)(n,{verse:61,children:"And he apprehended of the men of the country, that were the principal authors of the mischief, fifty men, and he slew them."}),"\n",(0,a.jsx)(n,{verse:62,children:"And Jonathan, and Simon, and they that were with him, retired into Bethbessen, which is in the desert: and he repaired the breaches thereof, and they fortified it."}),"\n",(0,a.jsx)(n,{verse:63,children:"And when Bacchides knew it, he gathered together all his multitude: and sent word to them that were of Judea."}),"\n",(0,a.jsx)(n,{verse:64,children:"And he came, and camped above Bethbessen, and fought against it many days, and made engines."}),"\n",(0,a.jsx)(n,{verse:65,children:"But Jonathan left his brother, Simon, in the city and went forth into the country, and came with a number of men,"}),"\n",(0,a.jsx)(n,{verse:66,children:"And struck Odares, and his brethren, and the children of Phaseron, in their tents, and he began to slay, and to increase in forces."}),"\n",(0,a.jsx)(n,{verse:67,children:"But Simon, and they that were with him, sallied out of the city, and burnt the engines,"}),"\n",(0,a.jsx)(n,{verse:68,children:"And they fought against Bacchides, and he was discomfited by them: and they afflicted him exceedingly, for his counsel, and his enterprise was in vain."}),"\n",(0,a.jsx)(n,{verse:69,children:"And he was angry with the wicked men that had given him counsel to come into their country, and he slew many of them: and he purposed to return with the rest into their country."}),"\n",(0,a.jsx)(n,{verse:70,children:"And Jonathan had knowledge of it, and he sent ambassadors to him to make peace with him, and to restore to him the prisoners."}),"\n",(0,a.jsx)(n,{verse:71,children:"And he accepted it willingly, and did according to his words, and swore that he would do him no harm all the days of his life."}),"\n",(0,a.jsx)(n,{verse:72,children:"And he restored to him the prisoners which he before had taken out of the land of Juda: and he returned, and went away into his own country, and he came no more into their borders."}),"\n",(0,a.jsx)(n,{verse:73,children:"So the sword ceased from Israel: and Jonathan dwelt in Machmas, and Jonathan began there to judge the people, and he destroyed the wicked out of Israel."})]})}function l(e={}){const{wrapper:t}={...(0,h.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(c,{...e})}):c(e)}},71184:(e,t,n)=>{n.d(t,{R:()=>r,x:()=>d});var a=n(14041);const h={},s=a.createContext(h);function r(e){const t=a.useContext(s);return a.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function d(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(h):e.components||h:r(e.components),a.createElement(s.Provider,{value:t},e.children)}}}]);